  "anomalies": [
    {
      "category": "wrong_component_type",
      "components": ["D2", "C14"],
      "pins": ["D2.1", "D2.2", "C14.1", "C14.2"],
      "nets": ["/Microcontroller/HEATER", "Net-(D2-K)"],
      "observed": "D2 (LED) anode is on the HEATER net and its cathode is on Net-(D2-K), which connects only to C14 (22uF) to GND. There is no series current-limiting resistor; the LED is in series with a 22uF capacitor to ground.",
      "expected": "The spec states a status LED D2 with a series resistor R3 on the HEATER net: 'A status LED (D2) and series resistor (R3) are also on the HEATER net'. A series resistor (R3) should be present to limit LED current; a capacitor in that position is not a valid indicator circuit.",
      "evidence": [
        {"source": "spec", "quote": "A status LED (D2) and series resistor (R3) are also on the HEATER net, so the heater output doubles as a visual 'heater on' indicator at the board level"},
        {"source": "netlist", "quote": "(net (code \"14\") (name \"Net-(D2-K)\") (class \"Default\") (node (ref \"C14\") (pin \"1\") (pintype \"passive\")) (node (ref \"D2\") (pin \"1\") (pinfunction \"K\") (pintype \"passive\")))"},
        {"source": "netlist", "quote": "(net (code \"4\") (name \"/Microcontroller/HEATER\") (class \"Default\") (node (ref \"D2\") (pin \"2\") (pinfunction \"A\") (pintype \"passive\"))"}
      ],
      "impact": "The heater-on indicator LED will not light continuously when the heater is on; instead it will only flash briefly while C14 charges, so the visual heater-on indication is effectively lost.",
      "confidence": 0.55
    }
  ],
  "summary": "The design largely matches the specification, but the heater status LED D2 is wired with a 22uF capacitor (C14) to ground in place of the specified series resistor R3, so the LED indicator will not function as intended."
}

